import { ASK_TEMPLATES, type MapAtom, type Part, parse } from './reference-ask';

/**
 * The fake agent's grammar, generated by code from the approved map and the section 5 table (docs/estate.md, "The
 * ask templates"), never from what the generator says about itself: for each atom that declares an act, every ask
 * a row of the table writes for it, with its context as the situation when the atom declares one. The declared act
 * is `fields.ask` (its text and context) when the map gives it, and each labelled governed-action span of the
 * atom's quote (`fields.labelSpans`, a verbatim slice with the labeller's provenance); an atom with neither has no
 * act and no ask sets it off; for a fixed act the table ties to a tool, every ask
 * a row writes with it, for each guard whose matcher lists the tool. The fake sets an atom off only when an ask
 * equals one of its texts byte for byte (dispatch.mjs). A `hypothetical` row asks what an act would mean and
 * requests none: its texts are listed apart (`hypothetical`), and the fake sets nothing off for them. Nothing reads
 * a word of an ask.
 */
export type AskGrammar = { asks: Record<string, string[]>; hypothetical: Record<string, string[]> };

type Fill = { act?: string; situation?: string; span?: string };

/** A template with its slots filled, the optional group written when `withGroup`; undefined if a slot is empty. */
function render(parts: readonly Part[], fill: Fill, withGroup: boolean): string | undefined {
  let out = '';
  for (const part of parts) {
    if ('lit' in part) out += part.lit;
    else if ('opt' in part) {
      if (!withGroup) continue;
      const inner = render(part.opt, fill, true);
      if (inner === undefined) return undefined;
      out += inner;
    } else {
      const value = fill[part.slot as keyof Fill];
      if (value === undefined) return undefined;
      out += value;
    }
  }
  return out;
}

const hasGroup = (parts: readonly Part[]): boolean => parts.some((part) => 'opt' in part);

const hasWord = (text: string): boolean => /[\p{L}\p{N}]/u.test(text) && text.trim() === text;

/**
 * The cuts a situation or description gives, by punctuation alone (docs/estate.md section 5: "the first sentence of
 * a skill's or helper's description"): the text whole, without its final mark, and its first sentence (up to the
 * first full stop followed by a space) without its mark. No word is read.
 */
function sentenceCuts(text: string): string[] {
  const bare = (value: string) => value.replace(/[.!?:;]+$/u, '');
  const stop = text.indexOf('. ');
  const cuts = [text, bare(text), ...(stop > 0 ? [bare(text.slice(0, stop))] : [])];
  return [...new Set(cuts.filter(hasWord))];
}

/**
 * The acts an atom declares in the map: `fields.ask` (a route's request cell, or a text with its context), its
 * trigger (`fields.trigger`), its quote (`provenance.quote`) and its situation, each whole, then each labelled
 * governed-action span of its quote. Empty when it declares none.
 */
export function declaredActs(atom: MapAtom): Array<{ text: string; context?: string }> {
  const fields = (atom.fields ?? {}) as { ask?: unknown; labelSpans?: unknown };
  const acts: Array<{ text: string; context?: string }> = [];
  const ask = fields.ask;
  if (typeof ask === 'string' && hasWord(ask)) acts.push({ text: ask });
  else if (ask !== null && typeof ask === 'object') {
    const { text, context } = ask as { text?: unknown; context?: unknown };
    if (typeof text === 'string' && hasWord(text))
      acts.push(typeof context === 'string' && hasWord(context) ? { text, context } : { text });
  }
  // The atom's verbatim source text, taken whole and never sliced (lead ruling): a gate's trigger, and the quote
  // of its unit.
  const trigger = (fields as { trigger?: unknown }).trigger;
  if (typeof trigger === 'string' && hasWord(trigger) && !acts.some((act) => act.text === trigger))
    acts.push({ text: trigger });
  const quote = atom.provenance?.quote;
  if (typeof quote === 'string' && hasWord(quote) && !acts.some((act) => act.text === quote))
    acts.push({ text: quote });
  // A route's description or a rule's situation, whole or cut at its first sentence (the generator asks from it).
  const situation = atom.situation;
  if (typeof situation === 'string')
    for (const cut of sentenceCuts(situation))
      if (!acts.some((act) => act.text === cut)) acts.push({ text: cut });
  const spans = (Array.isArray(fields.labelSpans) ? fields.labelSpans : []) as Array<{
    kind?: unknown;
    from?: unknown;
    to?: unknown;
  }>;
  if (typeof quote === 'string')
    for (const span of spans) {
      if (span.kind !== 'governed-action') continue;
      const text = quote.slice(Number(span.from), Number(span.to));
      if (hasWord(text) && !acts.some((act) => act.text === text)) acts.push({ text });
    }
  return acts;
}

export function askGrammar(atoms: readonly MapAtom[]): AskGrammar {
  const rows = (kind: string) =>
    ASK_TEMPLATES.filter((entry) => entry.kind === kind).map((entry) => ({
      kind,
      parts: parse(entry.template),
    }));
  const asks = [...rows('ask'), ...rows('hypothetical')];
  const out = new Map<string, Set<string>>();
  const apart = new Map<string, Set<string>>();
  const add = (kind: string, text: string | undefined, id: string) => {
    if (text === undefined) return;
    const into = kind === 'hypothetical' ? apart : out;
    into.set(text, (into.get(text) ?? new Set()).add(id));
  };
  const byId = new Map(atoms.map((atom) => [atom.id, atom]));
  // The situations an atom's ask may carry, whole: its declared context, its own situation and, for an atom whose
  // fields name others (a guard names the rule it enforces), theirs.
  const situationsOf = (atom: MapAtom): string[] => {
    const named = Object.values((atom.fields ?? {}) as Record<string, unknown>)
      .flatMap((value) => (Array.isArray(value) ? value : [value]))
      .filter((value): value is string => typeof value === 'string' && byId.has(value))
      .map((id) => byId.get(id) as MapAtom);
    const all = [atom, ...named].flatMap((one) => [
      ((one.fields as { ask?: { context?: unknown } } | undefined)?.ask as { context?: unknown } | undefined)
        ?.context,
      one.situation,
    ]);
    return [...new Set(all.filter((text): text is string => typeof text === 'string').flatMap(sentenceCuts))];
  };
  // Every ask of every row for one act, with no situation and with each the act may carry; `span` fills an ask
  // row whose slot is the declared words themselves.
  const write = (act: string, id: string, span: string | undefined, contexts: readonly string[]) => {
    for (const { kind, parts } of asks) {
      add(kind, render(parts, { act, ...(span === undefined ? {} : { span }) }, false), id);
      if (!hasGroup(parts)) continue;
      for (const situation of contexts)
        add(kind, render(parts, { act, ...(span === undefined ? {} : { span }), situation }, true), id);
    }
  };
  // The act rows with one `{span}`: each declared act is written in each of them.
  const actRows = ASK_TEMPLATES.filter((entry) => entry.kind === 'act')
    .map((entry) => parse(entry.template))
    .filter((parts) => parts.filter((part) => 'slot' in part).length === 1 && !hasGroup(parts));
  for (const atom of atoms) {
    const contexts = situationsOf(atom);
    for (const declared of declaredActs(atom))
      for (const row of actRows) {
        const act = render(row, { span: declared.text }, false);
        if (act !== undefined) write(act, atom.id, declared.text, contexts);
      }
  }
  for (const row of ASK_TEMPLATES) {
    const slotted = parse(row.template).some((part) => 'slot' in part);
    if (row.kind !== 'act' || row.tools === undefined || slotted) continue;
    for (const atom of atoms) {
      const matcher = (atom.fields as { matcher?: unknown } | undefined)?.matcher;
      if (atom.kind !== 'guard' || typeof matcher !== 'string') continue;
      if (!matcher.split('|').some((tool) => row.tools?.includes(tool))) continue;
      // The guard's tool act sets off the guard and the rule it enforces (an atom its fields name).
      const enforced = Object.values((atom.fields ?? {}) as Record<string, unknown>)
        .flatMap((value) => (Array.isArray(value) ? value : [value]))
        .filter((value): value is string => typeof value === 'string' && byId.has(value));
      for (const id of [atom.id, ...enforced]) write(row.template, id, undefined, situationsOf(atom));
    }
  }
  const listed = (map: Map<string, Set<string>>) => {
    const texts = [...map.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    return Object.fromEntries(texts.map((text) => [text, [...(map.get(text) ?? [])].sort()]));
  };
  return { asks: listed(out), hypothetical: listed(apart) };
}
